dist/common/styles.css.content:
/* Common owns only universal structure/scales. Families supply material DNA. */
@layer starci-grammar-common, starci-grammar-core, starci-grammar-heritage, starci-grammar-offset-pop;

@layer starci-grammar-common {
    .grammar-common-root {
        --grammar-inline-gap: 0.5rem;
        --grammar-row-gap: 0.75rem;
        --grammar-section-gap: 1rem;
        --grammar-region-gap: 1.5rem;
        --grammar-page-inset: clamp(1rem, 3vw, 2rem);
        min-width: 0;
    }

    .grammar-common-root,
    .grammar-common-root::before,
    .grammar-common-root::after,
    .grammar-common-root *,
    .grammar-common-root *::before,
    .grammar-common-root *::after {
        box-sizing: border-box;
    }

    /* Grammar scroll remains operable without adding persistent chrome to a composition. */
    .grammar-common-root,
    .grammar-common-root * {
        -ms-overflow-style: none;
        scrollbar-width: none;
    }

    .grammar-common-root::-webkit-scrollbar,
    .grammar-common-root *::-webkit-scrollbar {
        display: none;
        width: 0;
        height: 0;
    }

    .starci-core-page-container {
        width: min(100%, var(--starci-core-page-measure, 80rem));
        min-width: 0;
        margin-inline: auto;
        padding-inline: var(--starci-core-page-inset, clamp(1rem, 3vw, 2rem));
    }

    .starci-core-page-container[data-grammar-page-measure="reading"] {
        width: min(100%, var(--starci-core-reading-measure, 72ch));
    }

    .starci-core-page-container[data-grammar-page-measure="full"] {
        width: 100%;
    }

    .starci-core-section-header {
        display: flex;
        min-width: 0;
        align-items: flex-end;
        justify-content: space-between;
        gap: var(--starci-core-region-gap, 1.5rem);
    }

    .starci-core-section-header-copy {
        display: flex;
        min-width: 0;
        flex: 1;
        flex-direction: column;
        gap: 0.5rem;
    }

    .starci-core-section-title {
        margin: 0;
        max-width: 100%;
        color: var(--starci-core-foreground, var(--foreground, CanvasText));
        font-size: clamp(1.25rem, 1rem + 0.75cqi, 1.75rem);
        font-weight: 700;
        letter-spacing: -0.025em;
        line-height: 1.2;
        overflow-wrap: anywhere;
        text-wrap: balance;
    }

    .starci-core-section-eyebrow {
        color: var(--starci-core-accent, var(--accent, Highlight));
        font-size: 0.75rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        line-height: 1.25rem;
        text-transform: uppercase;
    }

    .starci-core-section-description,
    .starci-core-media-caption {
        color: var(--starci-core-muted, var(--muted, GrayText));
        font-size: 0.875rem;
        line-height: 1.5;
        overflow-wrap: anywhere;
    }

    .starci-core-section-action {
        flex: none;
    }

    .starci-core-visually-hidden {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
    }

    .starci-core-surface-copy-group {
        display: flex;
        min-width: 0;
        flex-direction: column;
        gap: 0.5rem;
    }

    .starci-core-surface-copy-group[data-grammar-copy-density="comfortable"] {
        gap: 0.75rem;
    }

    .starci-core-included-mark {
        display: inline-block;
        width: 1.25rem;
        height: 1.25rem;
        flex: none;
        color: inherit;
        vertical-align: text-bottom;
    }

    .starci-core-media-frame {
        display: flex;
        min-width: 0;
        margin: 0;
        flex-direction: column;
        gap: 0.5rem;
    }

    .starci-core-media-viewport {
        position: relative;
        min-width: 0;
        overflow: hidden;
        border: 1px solid var(--starci-core-border, var(--border, GrayText));
        border-radius: var(--starci-core-surface-radius, 1rem);
        background: var(--starci-core-surface-secondary, var(--surface-secondary, Canvas));
    }

    .starci-core-media-frame[data-grammar-media-aspect="landscape"] .starci-core-media-viewport { aspect-ratio: 16 / 10; }
    .starci-core-media-frame[data-grammar-media-aspect="portrait"] .starci-core-media-viewport { aspect-ratio: 4 / 5; }
    .starci-core-media-frame[data-grammar-media-aspect="square"] .starci-core-media-viewport { aspect-ratio: 1; }

    .starci-core-media-viewport > :where(img, picture, video, svg) {
        display: block;
        width: 100%;
        height: 100%;
        object-fit: cover;
    }

    .starci-core-media-frame[data-grammar-media-fit="contain"] .starci-core-media-viewport > :where(img, picture, video, svg) {
        object-fit: contain;
    }

    .starci-core-media-frame[data-grammar-media-treatment="plain"] .starci-core-media-viewport {
        border-color: transparent;
        background: transparent;
    }

    .starci-core-primary-rail-container {
        container: starci-core-primary-rail / inline-size;
        min-width: 0;
    }

    /*
     * THE COLLAPSED FORM IS THE DEFAULT. Every two-column form lives INSIDE the container query.
     *
     * A container query adds no specificity, so while the expanded tracks were written outside it
     * as attribute selectors, `[data-grammar-layout-rail-width="wide"]` (0,2,0) outranked the
     * collapse (0,1,0) and the layout never collapsed at all: in a 358px container the primary
     * track computed to 0px and the entire primary column vanished on a phone.
     *
     * Restating the collapse once per attribute value would repair today's three variants and break
     * again on the fourth one somebody adds. The two ranges are made MUTUALLY EXCLUSIVE instead:
     * the narrow form is what remains when the query does not match, so no selector inside the
     * query - at any specificity, with any attribute invented later - can outrank it. It is also
     * what a renderer without container queries gets, which is the safe half of the pair.
     */
    .starci-core-primary-rail-layout {
        display: grid;
        min-width: 0;
        grid-template-columns: minmax(0, 1fr);
        gap: var(--starci-core-region-gap, 1.5rem);
    }

    .starci-core-primary-rail-layout[data-grammar-layout-align="start"] { align-items: start; }
    .starci-core-primary-rail-layout[data-grammar-layout-align="stretch"] { align-items: stretch; }

    /* The rail track is spelled once per width, and only where there is a rail to give it to. */
    @container starci-core-primary-rail (min-width: 56.001rem) {
        .starci-core-primary-rail-layout[data-grammar-layout-rail="present"] { grid-template-columns: minmax(0, 1fr) minmax(16rem, 20rem); }
        .starci-core-primary-rail-layout[data-grammar-layout-rail="present"][data-grammar-layout-rail-width="compact"] { grid-template-columns: minmax(0, 1fr) minmax(14rem, 16rem); }
        .starci-core-primary-rail-layout[data-grammar-layout-rail="present"][data-grammar-layout-rail-width="wide"] { grid-template-columns: minmax(0, 1fr) minmax(20rem, 24rem); }
    }

    .starci-core-primary-region,
    .starci-core-rail-region {
        min-width: 0;
    }

    .starci-core-form-page {
        display: flex;
        min-height: 100dvh;
        padding: 1.5rem 1rem;
        align-items: center;
        justify-content: center;
        overflow: hidden;
    }

    .starci-core-form-scroll-viewport {
        width: 100%;
        max-height: calc(100dvh - 3rem);
        overscroll-behavior: contain;
    }

    .starci-core-form-surface {
        display: flex;
        width: min(100%, var(--starci-core-form-measure, 30rem));
        min-width: 0;
        flex-direction: column;
        gap: var(--starci-core-section-gap, 0.75rem);
    }

    .starci-core-form-surface--compact {
        width: min(100%, var(--starci-core-form-compact-measure, 28rem));
    }

    .starci-core-form-surface > .card,
    .starci-core-form-surface > .starci-core-surface,
    .starci-core-form-surface > .starci-core-surface-highlight {
        max-height: calc(100dvh - 3rem);
        overflow: hidden !important;
        padding: 0 !important;
    }

    .starci-core-form-surface > .starci-core-surface-highlight > .starci-core-surface {
        max-height: inherit;
    }

    .starci-core-form-field {
        display: flex;
        min-width: 0;
        flex-direction: column;
        gap: var(--starci-core-field-gap, 0.5rem);
    }

    .starci-core-form-label--screen-reader {
        position: absolute;
        width: 1px;
        height: 1px;
        padding: 0;
        margin: -1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
        border: 0;
    }

    /*
     * A field-shaped press target is FIELD anatomy, not a button variant.
     *
     * Two applications had already cloned it - a search trigger that looks exactly like the input
     * it replaces - and both did it by pushing field geometry into a Grammar Button through
     * `className`, which is an app override of a Grammar object. The anatomy lives here instead,
     * reading the same `--field-*` contract the Input primitive reads, so the two clones can be
     * deleted and no application has to restate the field's height, inset, corner or paint.
     */
    .starci-core-pressable-field {
        display: flex;
        width: 100%;
        min-width: 0;
        height: 2.25rem;
        align-items: center;
        justify-content: space-between;
        gap: 0.5rem;
        border: var(--field-border-width, 1px) solid var(--field-border, var(--border, ButtonBorder));
        border-radius: var(--field-radius, calc(var(--radius, 0.5rem) * 1.5));
        padding-inline: 0.75rem;
        background: var(--field-background, var(--surface, Canvas));
        color: var(--field-foreground, var(--foreground, CanvasText));
        box-shadow: var(--field-shadow, none);
        font: inherit;
        text-align: start;
        cursor: pointer;
        transition:
            background-color var(--starci-core-motion-duration, 180ms) var(--starci-core-motion-easing, cubic-bezier(0.2, 0, 0, 1)),
            border-color var(--starci-core-motion-duration, 180ms) var(--starci-core-motion-easing, cubic-bezier(0.2, 0, 0, 1));
        -webkit-appearance: none;
        appearance: none;
    }

    .starci-core-pressable-field:hover {
        border-color: var(--field-border-hover, var(--field-border, var(--border, ButtonBorder)));
        background: var(--field-hover, var(--field-background, var(--surface, Canvas)));
    }

    .starci-core-pressable-field:focus-visible {
        outline: 2px solid var(--focus, var(--starci-core-focus, Highlight));
        outline-offset: 2px;
    }

    .starci-core-pressable-field:disabled,
    .starci-core-pressable-field[data-disabled="true"] {
        opacity: 0.5;
        cursor: default;
    }

    .starci-core-pressable-field-content {
        display: inline-flex;
        min-width: 0;
        align-items: center;
        gap: 0.5rem;
    }

    .starci-core-pressable-field-placeholder {
        min-width: 0;
        overflow: hidden;
        font-size: 0.875rem;
        color: var(--field-placeholder, var(--muted, GrayText));
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .starci-core-pressable-field-shortcut {
        flex-shrink: 0;
        border: 1px solid var(--border, var(--starci-core-border, ButtonBorder));
        border-radius: var(--radius-sm, calc(var(--radius, 0.5rem) * 0.75));
        padding: 0.25rem;
        background: var(--surface-secondary, var(--starci-core-surface-secondary, Canvas));
        color: var(--muted, var(--starci-core-muted, GrayText));
        font-family: inherit;
        font-size: 0.75rem;
        line-height: 1;
    }

    @media (prefers-reduced-motion: reduce) {
        .starci-core-pressable-field {
            transition: none;
        }
    }

    /*
     * One scrolling axis, drawn by the family's own sheet.
     *
     * The vendor's `.scroll-shadow--horizontal` sets `overflow-x: auto` alone, and a computed
     * `overflow-x: auto` forces `overflow-y` to compute to `auto` as well, so the region rendered
     * `overflow: auto auto` - two scrolling axes under an OVERFLOW-3 claim that promises one. Naming
     * both axes here keeps the render at the one axis the claim describes.
     */
    .starci-core-horizontal-scroll-region {
        width: 100%;
        min-width: 0;
        padding-block: 0.25rem;
        overflow-x: auto;
        overflow-y: hidden;
        overscroll-behavior-inline: contain;
    }

    .starci-core-horizontal-scroll-region > * {
        width: max-content;
        min-width: max-content;
    }

    /*
     * The same one scrolling axis, for the vertical region.
     *
     * The vendor's `.scroll-shadow--vertical` sets `overflow-y: auto` alone, and every host class
     * this region wears - the chat conversation, the chat overlay rail, the accordion region, the
     * form scroll viewport - names that same single axis or names none at all. A computed non-visible
     * overflow on one axis forces the other from `visible` to `auto`, so the region rendered
     * `overflow: auto auto`: two scrolling axes under an OVERFLOW-3 claim that promises one. Naming
     * both axes on the region's own identity holds the render at the one axis the claim describes,
     * and needs no `!important` to do it: no host class and no vendor rule ever names `overflow-x`,
     * so this declaration is unopposed whichever order a consumer imports the two sheets in.
     */
    [data-grammar-scroll-region="vertical"] {
        overflow-x: hidden;
        overflow-y: auto;
    }

    @media (min-width: 40rem) {
        .starci-core-form-page {
            padding-block: 2.5rem;
        }

        .starci-core-form-scroll-viewport {
            max-height: calc(100dvh - 5rem);
        }

        .starci-core-form-surface > .card,
        .starci-core-form-surface > .starci-core-surface,
        .starci-core-form-surface > .starci-core-surface-highlight {
            max-height: calc(100dvh - 5rem);
        }
    }

    .starci-core-surface-card,
    .starci-core-surface-list,
    .starci-core-surface-accordion-card {
        container-name: starci-core-surface;
        container-type: inline-size;
        display: flex;
        min-width: 0;
        width: 100%;
        flex-direction: column;
        gap: var(--starci-core-section-gap, 0.75rem);
    }

    .starci-core-surface-label {
        display: flex;
        min-width: 0;
        align-items: baseline;
        justify-content: space-between;
        gap: var(--starci-core-inline-gap, 0.5rem);
    }

    .starci-core-surface-label > :first-child {
        min-width: 0;
        margin: 0;
    }

    .starci-core-label {
        min-width: 0;
        margin: 0;
        font-size: 0.875rem;
        font-weight: 600;
        line-height: 1.25rem;
    }

    .starci-core-label[data-grammar-label-depth="nested"] {
        font-size: 0.75rem;
        line-height: 1rem;
    }

    .starci-core-tooltip {
        position: relative;
        max-width: fit-content;
    }

    .starci-core-tooltip-content {
        position: absolute;
        z-index: 20;
        pointer-events: none;
        white-space: nowrap;
        border-radius: var(--starci-core-control-radius, 0.75rem);
        background: var(--starci-core-foreground, var(--foreground, CanvasText));
        color: var(--starci-core-canvas, var(--background, Canvas));
        padding: 0.25rem 0.5rem;
        font-size: 0.75rem;
        line-height: 1rem;
        font-weight: 500;
        opacity: 0;
        transition:
            opacity var(--starci-core-motion-duration, 180ms) var(--starci-core-motion-easing, cubic-bezier(0.2, 0, 0, 1)),
            visibility var(--starci-core-motion-duration, 180ms) var(--starci-core-motion-easing, cubic-bezier(0.2, 0, 0, 1));
        visibility: hidden;
    }

    .starci-core-tooltip:hover > .starci-core-tooltip-content,
    .starci-core-tooltip:focus-within > .starci-core-tooltip-content {
        opacity: 1;
        visibility: visible;
    }

    .starci-core-tooltip[data-grammar-tooltip-placement="top"] > .starci-core-tooltip-content {
        bottom: calc(100% + 0.375rem);
        left: 50%;
        transform: translateX(-50%);
    }

    .starci-core-tooltip[data-grammar-tooltip-placement="bottom"] > .starci-core-tooltip-content {
        top: calc(100% + 0.375rem);
        left: 50%;
        transform: translateX(-50%);
    }

    @media (prefers-reduced-motion: reduce) {
        .starci-core-tooltip-content {
            transition: none;
        }
    }

    .starci-core-surface {
        position: relative;
        min-width: 0;
        overflow: hidden;
        border-radius: var(--starci-core-surface-radius, 1rem);
        background: var(--surface, Canvas);
        color: var(--surface-foreground, CanvasText);
    }

    @property --starci-core-highlight-angle {
        syntax: "<angle>";
        initial-value: 0deg;
        inherits: false;
    }

    @keyframes starci-core-highlight-spin {
        to {
            --starci-core-highlight-angle: 360deg;
        }
    }

    .starci-core-surface-highlight {
        border-radius: var(--starci-core-surface-radius, 1rem);
        overflow: visible;
    }

    .starci-core-surface-highlight-sweep {
        position: absolute;
        z-index: 1;
        inset: var(--starci-core-highlight-inset, 0);
        box-sizing: border-box;
        border-radius: inherit;
        padding: 2px;
        background: conic-gradient(
            from var(--starci-core-highlight-angle),
            transparent 0%,
            transparent 82%,
            var(--starci-core-accent, var(--accent, Highlight)) 92%,
            transparent 100%
        );
        -webkit-mask:
            linear-gradient(#000 0 0) content-box,
            linear-gradient(#000 0 0);
        -webkit-mask-composite: xor;
        mask:
            linear-gradient(#000 0 0) content-box,
            linear-gradient(#000 0 0);
        mask-composite: exclude;
        animation: starci-core-highlight-spin 3s linear infinite;
        pointer-events: none;
    }

    @media (prefers-reduced-motion: reduce) {
        .starci-core-surface-highlight-sweep {
            animation: none;
        }
    }

    .starci-core-surface[data-grammar-surface-depth="top"] {
        border: 0;
        box-shadow: var(--starci-core-surface-shadow, var(--shadow-surface, 0 1px 3px rgb(0 0 0 / 0.16)));
    }

    .starci-core-surface[data-grammar-surface-depth="nested"] {
        border: 1px solid var(--border, GrayText);
        box-shadow: none;
    }

    .starci-core-surface-content {
        min-width: 0;
        padding: var(--starci-core-surface-inset, 1rem);
    }

