     * stacking are already spelled by the data attributes these compositions emit, and a custom
     * property set on the root inherits to every page inside it. The root - not `:root` - keeps the
     * package inside its own boundary, which is the same reason no rule here touches the document.
     *
     * NOTHING is defined when no sticky band is present, so `var(--starci-core-band-offset, X)`
     * still resolves to a consumer's own X exactly as it did before this property existed.
     */
    .grammar-common-root:has(.starci-core-navigation-feature-nav[data-grammar-navigation-feature-nav-position="sticky"]),
    .grammar-common-root:has(.starci-core-subnav[data-grammar-subnav-position="sticky"]) {
        --starci-core-band-offset: calc(var(--starci-core-band-height, 0rem) + var(--starci-core-band-subnav-height, 0rem));
    }

    .grammar-common-root:has(.starci-core-navigation-feature-nav[data-grammar-navigation-feature-nav-position="sticky"]) {
        --starci-core-band-height: calc(4rem + 1px);
    }

    .grammar-common-root:has(.starci-core-navigation-feature-nav[data-grammar-navigation-feature-nav-position="sticky"][data-grammar-navigation-feature-nav-layers="two"]) {
        --starci-core-band-height: calc(4rem + 2rem + 1px);
    }

    /* A sticky Subnav stacks under the band, so it adds its own height and separator to the offset. */
    .grammar-common-root:has(.starci-core-subnav[data-grammar-subnav-position="sticky"]) {
        --starci-core-band-subnav-height: calc(3.25rem + 1px);
    }

    .starci-core-navigation-feature-nav-primary {
        display: grid !important;
        min-height: 4rem;
        grid-template-columns: minmax(0, 1fr) auto auto !important;
        align-items: center;
        gap: var(--starci-core-row-gap, 0.75rem);
        padding-block: var(--starci-core-inline-gap, 0.5rem);
    }

    .starci-core-navigation-feature-nav-primary.starci-core-page-container {
        padding-inline: 0.75rem;
    }

    .starci-core-navigation-feature-nav-identity,
    .starci-core-navigation-feature-nav-navigation,
    .starci-core-navigation-feature-nav-compact-navigation,
    .starci-core-navigation-feature-nav-actions,
    .starci-core-navigation-feature-nav-feature {
        min-width: 0;
    }

    .starci-core-navigation-feature-nav-navigation {
        display: none !important;
    }

    /*
     * A bar with no primary destinations renders no `nav` at all, so the grid loses a track rather
     * than keeping an empty one: identity leads, the remaining row belongs to what is still there.
     */
    .starci-core-navigation-feature-nav[data-grammar-navigation-feature-nav-destinations="absent"] .starci-core-navigation-feature-nav-primary {
        grid-template-columns: minmax(0, 1fr) auto !important;
    }

    .starci-core-navigation-feature-nav-compact-navigation {
        display: block !important;
    }

    .starci-core-navigation-feature-nav-actions {
        display: flex;
        align-items: center;
        justify-content: end;
        gap: var(--starci-core-inline-gap, 0.5rem);
    }

    /*
     * THE BAND'S OWN CONTROLS MEET THE 44px TOUCH FLOOR.
     *
     * Every pressable in the two action slots was the vendor button's own height - 2.25rem on
     * desktop and 2.5rem compact - so the language menu, the cart, the account button, the compact
     * drawer trigger and the field-shaped search trigger all sat under the floor, on the surface a
     * reader is most likely to touch. It is a MINIMUM, not a size: `min-inline-size` and
     * `min-block-size` are properties the vendor's rules never set, so the glyph, the label, the
     * paint and the corner are all untouched and no `!important` is owed to the components layer.
     *
     * The band does NOT grow. The primary row is 4rem with a 0.5rem block inset on each side, so
     * 44px is 4px short of the 3rem it already offers a control, and `--starci-core-band-height`
     * stays `calc(4rem + 1px)`. The floor is spelled on the pressable, never on the slot: a slot
     * with a min-height would pad a row that has nothing in it.
     *
     * The feature layer is deliberately out of scope - its tabs are a Tabs branch, and a tab's
     * target is that branch's to answer.
     *
     * The primary destinations in the `navigation` slot carry the identical selector: a
     * `route`-appearance TextAction already meets the floor on its own (below), but the slot rule
     * is the family's general-purpose net for ANY pressable a consumer puts there, the same way the
     * action slots protect a control regardless of which leaf renders it.
     */
    .starci-core-navigation-feature-nav-actions :where(button, [role="button"], a[href]),
    .starci-core-navigation-feature-nav-navigation :where(button, [role="button"], a[href]),
    .starci-core-navigation-feature-nav-compact-navigation :where(button, [role="button"], a[href]) {
        min-inline-size: 44px;
        min-block-size: 44px;
    }

    /*
     * The identity slot's brand link is a `plain` TextAction used as a same-document pressable, not
     * a route: `plain` elsewhere in the family stays a compact inline mark with no reserved hit
     * area, so the floor is scoped to this one band slot instead of the bare `[data-appearance]`
     * rule, which would grow every quiet inline action across the app that never claimed to be a
     * touch target.
     */
    .starci-core-navigation-feature-nav-identity .starci-core-text-action[data-appearance="plain"] {
        min-block-size: var(--starci-core-control-min-size, 2.75rem);
    }

    .starci-core-navigation-feature-nav-feature {
        width: 100%;
        padding-inline: 0.75rem;
    }

    .starci-core-course-section-navigation {
        padding-inline-start: 0.75rem;
        padding-inline-end: 0.75rem;
    }

    /* The navbar owns the only outer separator; HeroUI's secondary tab rail must not add a twin. */
    .starci-core-navigation-feature-nav-feature .tabs__list-container {
        border-bottom-width: 0 !important;
    }

    /* Feature tabs share the dashboard rail's left inset; scroll chrome must not reclaim it. */
    .starci-core-navigation-feature-nav-feature .starci-core-tabs-scroll {
        padding-block: 0;
        padding-inline-start: 0;
    }

    .starci-core-navigation-feature-nav-feature .tabs__list-container__scroll-prev[disabled],
    .starci-core-navigation-feature-nav-feature .tabs__list-container__scroll-prev[tabindex="-1"] {
        width: 0;
        min-width: 0;
        padding: 0;
        margin: 0;
        overflow: hidden;
        opacity: 0;
        pointer-events: none;
    }

    .starci-core-navigation-feature-nav-feature .starci-core-tabs .tabs__indicator {
        bottom: 0 !important;
        inset-block-end: 0 !important;
    }

    .starci-core-course-section-navigation .tabs__list-container {
        border-bottom-width: 0 !important;
    }

    .starci-core-subnav {
        display: flex;
        width: 100%;
        min-width: 0;
        min-height: 3.25rem;
        align-items: center;
        justify-content: space-between;
        gap: var(--starci-core-row-gap, 0.75rem);
        padding-inline: 0.75rem;
        border-bottom: 1px solid var(--separator, var(--starci-core-separator, GrayText));
        background: var(--background, var(--starci-core-canvas, Canvas));
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
    }

    .starci-core-subnav[data-grammar-subnav-position="sticky"] {
        position: sticky;
        z-index: var(--starci-core-subnav-z, 40);
        /* The band's own published height, so a stacked Subnav no longer needs a consumer's calc. */
        top: var(--starci-core-subnav-offset, var(--starci-core-band-height, 4rem));
        backface-visibility: hidden;
        transform: translateZ(0);
        will-change: transform;
    }

    .starci-core-subnav-identity {
        display: flex;
        min-width: 0;
        align-items: center;
        gap: var(--starci-core-inline-gap, 0.5rem);
    }

    .starci-core-subnav-leading,
    .starci-core-subnav-toggle {
        flex: none;
    }

    .starci-core-subnav-title {
        display: flex;
        min-width: 0;
        overflow: hidden;
        align-items: center;
        font-weight: 600;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    /*
     * The toggle is a HeroUI `Button`, whose own fill, corner and shadow live in the vendor's
     * `components` layer - declared after `starci-grammar-common`, so it wins every normal
     * declaration here regardless of specificity. These are the ones the utilities used to carry,
     * so they are the ones that have to be important - the 2.75rem target included, because the
     * vendor sizes its own button and a consumer was re-forcing `size-11` to get the target back.
     */
    .starci-core-subnav-toggle {
        display: inline-flex;
        width: 2.75rem !important;
        height: 2.75rem !important;
        align-items: center;
        justify-content: center;
        border-radius: 0 !important;
        background: transparent !important;
        box-shadow: none !important;
        color: inherit;
        cursor: pointer;
    }

    .starci-core-subnav-toggle:hover,
    .starci-core-subnav-toggle[data-hovered="true"] {
        background: transparent !important;
    }

    @media (min-width: 48rem) {
        .starci-core-navigation-feature-nav[data-grammar-navigation-feature-nav-destinations="absent"] .starci-core-navigation-feature-nav-primary {
            grid-template-columns: auto minmax(0, 1fr) !important;
        }

        .starci-core-navigation-feature-nav-primary {
            grid-template-columns: auto minmax(0, 1fr) auto !important;
        }

        .starci-core-navigation-feature-nav-navigation {
            display: block !important;
        }

        .starci-core-navigation-feature-nav-compact-navigation {
            display: none !important;
        }
    }

    @media (min-width: 70rem) {
        .starci-core-subnav[data-grammar-subnav-visibility="compact"] {
            display: none;
        }

        /* A compact Subnav is not on screen here, so it contributes no height to the band offset. */
        .grammar-common-root:has(.starci-core-subnav[data-grammar-subnav-position="sticky"][data-grammar-subnav-visibility="compact"]) {
            --starci-core-band-subnav-height: 0rem;
        }
    }

    .starci-core-workspace-shell {
        position: relative;
        min-width: 0;
        container: starci-core-workspace-shell / inline-size;
    }

    .starci-core-workspace-shell-header {
        min-width: 0;
        margin-block-end: var(--starci-core-region-gap, 1.5rem);
    }

    .starci-core-workspace-shell-compact-header,
    .starci-core-workspace-shell-compact-navigation {
        display: none;
    }

    /*
     * THE COLLAPSED FORM IS THE DEFAULT here too, for the reason recorded on
     * `.starci-core-primary-rail-layout`: every multi-track form lives INSIDE a container query, so
     * the stacked one cannot be outranked by an attribute selector written outside it. Before this,
     * the two-track rule for `[navigation="present"][rail="present"]` (0,3,0) in the 72rem query
     * beat the collapse group's bare class (0,1,0), and the leading four-track rule (0,4,0) beat
     * every collapse rule there is, so a shell carrying a navigation and a rail never stacked.
     *
     * The tiers are mutually exclusive ranges, narrowest first:
     *   default        one column, one row per region
     *   > 56rem        the regions take their own tracks
     *   > 72rem        a navigation AND a rail stand beside the primary at the same time
     */
    .starci-core-workspace-shell-layout {
        --starci-core-workspace-navigation-track: minmax(14rem, var(--starci-core-workspace-navigation-width, 18rem));
        --starci-core-workspace-rail-track: minmax(16rem, var(--starci-core-rail-standard, 20rem));
        display: grid;
        min-width: 0;
        grid-template-areas: "navigation" "primary" "rail";
        grid-template-columns: minmax(0, 1fr);
        gap: var(--starci-core-region-gap, 1.5rem);
    }

    .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-track="intrinsic"] {
        --starci-core-workspace-navigation-track: max-content;
    }

    /* Stacked, an absent region leaves no row behind - an empty one would still take a gap. */
    .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="absent"] {
        grid-template-areas: "primary" "rail";
    }

    .starci-core-workspace-shell-layout[data-grammar-workspace-rail="absent"] {
        grid-template-areas: "navigation" "primary";
    }

    .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="absent"][data-grammar-workspace-rail="absent"] {
        grid-template-areas: "primary";
    }

    /* A leading rail keeps its precedence in the reading order once the tracks are gone. */
    .starci-core-workspace-shell-layout[data-grammar-workspace-rail-position="leading"][data-grammar-workspace-navigation="absent"][data-grammar-workspace-rail="present"] {
        grid-template-areas: "rail" "primary";
    }

    .starci-core-workspace-shell-leading-rule {
        display: none;
        grid-area: rule;
        width: 1px;
        align-self: stretch;
        justify-self: stretch;
        background: var(--separator, var(--starci-core-separator, GrayText));
    }

    @container starci-core-workspace-shell (min-width: 56.001rem) {
        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="present"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "navigation primary" "navigation rail";
            grid-template-columns: var(--starci-core-workspace-navigation-track) minmax(0, 1fr);
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="absent"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "primary rail";
            grid-template-columns: minmax(0, 1fr) var(--starci-core-workspace-rail-track);
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="present"][data-grammar-workspace-rail="absent"] {
            grid-template-areas: "navigation primary";
            grid-template-columns: var(--starci-core-workspace-navigation-track) minmax(0, 1fr);
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="absent"][data-grammar-workspace-rail="absent"] {
            grid-template-areas: "primary";
            grid-template-columns: minmax(0, 1fr);
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-rail-position="leading"][data-grammar-workspace-navigation="absent"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "rail rule primary";
            grid-template-columns: var(--starci-core-workspace-rail-track) 1px minmax(0, 1fr);
            column-gap: 0;
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-rail-position="leading"][data-grammar-workspace-navigation="present"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "navigation rail rule primary";
            grid-template-columns:
                var(--starci-core-workspace-navigation-track)
                var(--starci-core-workspace-rail-track)
                1px
                minmax(0, 1fr);
            column-gap: 0;
        }

        /* The seam and its rule belong to the side-by-side form, so they arrive with the tracks. */
        .starci-core-workspace-shell-layout[data-grammar-workspace-rail-position="leading"] .starci-core-workspace-shell-leading-rule {
            display: block;
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-rail-position="leading"] .starci-core-workspace-shell-primary {
            padding-inline-start: var(--starci-core-workspace-leading-seam, 2rem);
        }
    }

    @container starci-core-workspace-shell (min-width: 72.001rem) {
        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation="present"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "navigation primary rail";
            grid-template-columns:
                var(--starci-core-workspace-navigation-track)
                minmax(0, 1fr)
                var(--starci-core-workspace-rail-track);
        }
    }

    .starci-core-workspace-shell-layout[data-grammar-workspace-rail-width="compact"] {
        --starci-core-workspace-rail-track: minmax(14rem, var(--starci-core-rail-compact, 16rem));
    }

    .starci-core-workspace-shell-layout[data-grammar-workspace-rail-width="wide"] {
        --starci-core-workspace-rail-track: minmax(20rem, var(--starci-core-rail-wide, 24rem));
    }

    .starci-core-workspace-shell-layout[data-grammar-workspace-align="start"] { align-items: start; }
    .starci-core-workspace-shell-layout[data-grammar-workspace-align="stretch"] { align-items: stretch; }
    .starci-core-workspace-shell-navigation { grid-area: navigation; }
    .starci-core-workspace-shell-primary { grid-area: primary; }
    .starci-core-workspace-shell-rail { grid-area: rail; }

    .starci-core-workspace-shell-navigation,
    .starci-core-workspace-shell-primary,
    .starci-core-workspace-shell-rail {
        width: 100%;
        min-width: 0;
    }

    .starci-core-workspace-shell-primary {
        display: flex;
        flex-direction: column;
        gap: var(--starci-core-region-gap, 1.5rem);
        outline: none;
    }

    .starci-core-workspace-shell-floating-layer {
        position: fixed;
        z-index: var(--starci-core-workspace-floating-z, 40);
        inset-inline-end: var(--starci-core-workspace-floating-inset, 1rem);
        inset-block-end: max(var(--starci-core-workspace-floating-inset, 1rem), env(safe-area-inset-bottom));
        max-inline-size: min(var(--starci-core-workspace-floating-max, 22rem), calc(100vw - 2 * var(--starci-core-workspace-floating-inset, 1rem)));
        max-block-size: calc(100dvh - 2 * var(--starci-core-workspace-floating-inset, 1rem));
        overflow: auto;
        overscroll-behavior: contain;
    }

    /*
     * Sidebar geometry is SHIPPED, not generated.
     *
     * Every rule below used to be a Tailwind utility string in the component's JSX, which means a
     * consumer only saw a sidebar if its own Tailwind build happened to scan
     * `node_modules/@starci/grammar`. One that scans only its own source got no separator, no rail
     * width and square items - and `rounded-large` emitted nothing anywhere, because the theme's
     * radius ramp is `--radius-*`, not a HeroUI v2 name. A composition object owns its layout in
     * this stylesheet; the JSX carries class names and state attributes only.
     *
     * `!important` appears exactly where HeroUI's own `.list-box`, `.list-box-item`,
     * `.list-box-section` and `.header` rules set the same property. Those live in the vendor's
     * `components` layer, which is declared after `starci-grammar-common` and therefore wins every
     * normal declaration regardless of specificity; an important declaration in the earlier layer
     * is the only thing that keeps the geometry the utilities used to produce.
     */
    .starci-core-sidebar {
        display: flex;
        min-height: 0;
        min-width: 0;
        flex-direction: column;
        overflow: hidden;
        background: var(--background, var(--starci-core-canvas, Canvas));
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
    }

    .starci-core-sidebar[data-presentation="drawer"] {
        width: 100%;
    }

    .starci-core-sidebar[data-presentation="rail"] {
        width: var(--starci-core-sidebar-width, 16rem);
        height: 100%;
        border-inline-end: 1px solid var(--separator, var(--starci-core-separator, GrayText));
        transition: width var(--starci-core-motion-duration, 180ms) var(--starci-core-motion-easing, cubic-bezier(0.2, 0, 0, 1));
    }

    .starci-core-sidebar[data-presentation="rail"][data-collapsed="true"] {
        width: var(--starci-core-sidebar-collapsed-width, 4rem);
    }

    .starci-core-sidebar-toggle {
        display: flex;
        justify-content: flex-end;
        padding: 0.5rem;
    }

    .starci-core-sidebar[data-collapsed="true"] .starci-core-sidebar-toggle {
        justify-content: center;
    }

    .starci-core-sidebar-header {
        min-width: 0;
        padding-inline: 0.75rem;
        padding-block-end: 0.75rem;
    }

    .starci-core-sidebar-list {
        display: flex;
        min-height: 0;
        min-width: 0;
        flex: 1 1 0%;
        flex-direction: column;
        gap: 0.25rem;
        overflow-y: auto !important;
        padding: 0.75rem !important;
    }

    .starci-core-sidebar[data-collapsed="true"] .starci-core-sidebar-list {
        align-items: center;
        padding: 0.5rem !important;
    }

    .starci-core-sidebar-section {
        display: flex;
        min-width: 0;
        flex-direction: column;
        gap: 0.25rem !important;
    }

    .starci-core-sidebar[data-collapsed="true"] .starci-core-sidebar-section {
        align-items: center !important;
    }

    .starci-core-sidebar-section-label {
        padding-inline: 0.5rem;
        padding-block: 0.75rem 0.25rem !important;
        font-size: 0.75rem;
        font-weight: 500;
        color: var(--muted, var(--starci-core-muted, GrayText));
    }

    /* A collapsed rail keeps the group name for assistive technology and drops it from the paint. */
    .starci-core-sidebar[data-collapsed="true"] .starci-core-sidebar-section-label {
        position: absolute;
        width: 1px !important;
        height: 1px;
        overflow: hidden;
        margin: -1px;
        padding: 0 !important;
        border: 0;
        clip: rect(0, 0, 0, 0);
        white-space: nowrap;
    }

    .starci-core-sidebar-item {
        display: flex;
        min-width: 0;
        align-items: center;
        gap: 0.75rem;
        border-radius: var(--radius-xl, calc(var(--radius, 0.5rem) * 1.5)) !important;
        padding: 0.5rem 0.75rem !important;
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
        cursor: pointer;
        outline: none;
    }

    .starci-core-sidebar[data-collapsed="true"] .starci-core-sidebar-item {
        width: 2.75rem !important;
        height: 2.75rem;
        justify-content: center !important;
        gap: 0 !important;
        border-radius: var(--starci-core-pill-radius, 999px) !important;
        padding: 0 !important;
    }

    .starci-core-sidebar-item[data-hovered="true"] {
        background: var(--default, var(--starci-core-surface-secondary, Canvas));
    }

    .starci-core-sidebar-item[data-selected="true"] {
        background: var(--accent-soft, var(--starci-core-accent, Highlight)) !important;
        color: var(--accent-soft-foreground, var(--starci-core-accent, HighlightText));
    }

    .starci-core-sidebar-item[data-focus-visible="true"] {
        box-shadow: 0 0 0 2px var(--accent, var(--starci-core-accent, Highlight));
    }

    .starci-core-sidebar-item[data-disabled="true"] {
        opacity: 0.5;
        cursor: default;
    }

    .starci-core-sidebar-item-label {
        min-width: 0;
        flex: 1 1 0%;
        overflow: hidden;
        font-size: 0.875rem;
        font-weight: 500;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .starci-core-sidebar-item-trailing {
        flex-shrink: 0;
    }

    .starci-core-sidebar-footer {
        min-width: 0;
        padding: 0.75rem;
        padding-block-start: 0;
    }

    @media (prefers-reduced-motion: reduce) {
        .starci-core-sidebar[data-presentation="rail"] {
            transition: none;
        }
    }

    .starci-core-chat-workspace {
        display: flex;
        height: 100%;
        min-height: 0;
        min-width: 0;
        flex-direction: column;
        overflow: hidden;
        background: var(--background, var(--starci-core-canvas, Canvas));
    }

    .starci-core-chat-workspace-header,
    .starci-core-chat-workspace-composer,
    .starci-core-chat-workspace-rail-trigger-boundary {
        min-width: 0;
        flex: none;
    }

    .starci-core-chat-workspace-rail-trigger-boundary {
        display: flex;
        justify-content: flex-end;
        padding: 0.5rem 1rem;
        border-bottom: 1px solid var(--separator, var(--starci-core-separator, GrayText));
    }

    .starci-core-chat-workspace-rail-trigger {
        display: inline-flex;
        min-width: 2.75rem;
        min-height: 2.75rem;
        align-items: center;
        justify-content: center;
        padding-inline: 0.75rem;
        border: 1px solid var(--separator, var(--starci-core-separator, GrayText));
        border-radius: var(--starci-core-control-radius, 0.75rem);
        background: var(--surface, var(--starci-core-surface, Canvas));
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
        font-size: 0.875rem;
        font-weight: 500;
    }

    .starci-core-chat-workspace-rail-trigger:focus-visible,
    .starci-core-chat-workspace-conversation:focus-visible,
    .starci-core-chat-workspace-overlay-rail:focus-visible {
        outline: 2px solid var(--focus, var(--starci-core-focus, Highlight));
        outline-offset: -2px;
    }

    .starci-core-chat-workspace-layout {
        display: grid;
        min-height: 0;
        min-width: 0;
        flex: 1;
        grid-template-columns: minmax(0, 1fr);
        gap: var(--starci-core-region-gap, 1.5rem);
    }

    .starci-core-chat-workspace-layout-without-rail {
        grid-template-columns: minmax(0, 1fr);
    }

    .starci-core-chat-workspace-primary {
        display: flex;
        min-height: 0;
        min-width: 0;
        flex-direction: column;
        overflow: hidden;
    }

    .starci-core-chat-workspace-conversation {
        min-height: 0;
        min-width: 0;
        flex: 1;
        overflow-y: auto;
        overscroll-behavior: contain;
        scroll-behavior: smooth;
    }

    .starci-core-chat-workspace-composer {
        border-top: 1px solid var(--separator, var(--starci-core-separator, GrayText));
        background: var(--background, var(--starci-core-canvas, Canvas));
    }

    .starci-core-chat-workspace-inline-rail { display: none; }

    .starci-core-chat-workspace-drawer-content {
        right: 0 !important;
        left: auto !important;
        width: min(24rem, calc(100dvw - 1rem)) !important;
        max-width: calc(100dvw - 1rem) !important;
    }

    .starci-core-chat-workspace-drawer-dialog {
        width: 100% !important;
        height: 100% !important;
        min-height: 0 !important;
        max-width: none !important;
    }

    .starci-core-chat-workspace-drawer-body {
        min-height: 0;
        min-width: 0;
        padding: 0;
        overflow: hidden;
    }

    .starci-core-chat-workspace-overlay-rail {
        height: 100%;
        min-height: 0;
        min-width: 0;
        padding: 1rem;
        overflow-y: auto;
        overscroll-behavior: contain;
    }

    .starci-core-chat-workspace-drawer-close {
        width: 2.5rem !important;
        height: 2.5rem !important;
        border: 1px solid var(--separator, var(--starci-core-separator, GrayText)) !important;
        border-radius: 999px !important;
        background: var(--surface, var(--starci-core-surface, Canvas)) !important;
        color: var(--foreground, var(--starci-core-foreground, CanvasText)) !important;
    }

    @container starci-core-workspace-shell (max-width: 72rem) {
        .starci-core-workspace-shell-rail .starci-core-rail {
            max-width: none;
        }
    }

    /*
     * Every grid template this shell can take now lives in the two `min-width` tiers above. What
     * stays here is the behaviour of a STACKED rail, which no rule outside the query contradicts.
     */
    @container starci-core-workspace-shell (max-width: 56rem) {
        .starci-core-workspace-shell-rail .starci-core-rail-frame {
            position: static;
            max-height: none;
        }

        .starci-core-workspace-shell-rail .starci-core-rail-body {
            overflow-y: visible;
        }
    }

    @media (max-width: 69.999rem) {
        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-visibility="wide"] .starci-core-workspace-shell-navigation {
            display: none;
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-visibility="wide"][data-grammar-workspace-rail="absent"] {
            grid-template-areas: "primary";
            grid-template-columns: minmax(0, 1fr);
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-visibility="wide"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "primary" "rail";
            grid-template-columns: minmax(0, 1fr);
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-visibility="wide"][data-grammar-workspace-rail-position="leading"][data-grammar-workspace-rail="present"] {
            grid-template-areas: "rail" "primary";
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-visibility="wide"] .starci-core-workspace-shell-leading-rule {
            display: none;
        }

        .starci-core-workspace-shell-layout[data-grammar-workspace-navigation-visibility="wide"] .starci-core-workspace-shell-primary {
            padding-inline-start: 0;
        }

        .starci-core-workspace-shell-compact-header {
            display: block;
        }

        .starci-core-workspace-shell-compact-navigation {
            position: sticky;
            z-index: 40;
            inset-block-end: 0;
            display: flex;
            min-width: 0;
            align-items: center;
            justify-content: space-between;
            gap: var(--starci-core-inline-gap, 0.5rem);
            border-block-start: 1px solid var(--separator, var(--starci-core-separator, GrayText));
            background: var(--background, var(--starci-core-canvas, Canvas));
            padding: 0.75rem 1rem;
        }
    }

    @media (min-width: 48rem) {
        .starci-core-chat-workspace-layout[data-grammar-chat-workspace-rail-width="compact"] {
            grid-template-columns: minmax(0, 1fr) minmax(14rem, var(--starci-core-rail-compact, 16rem));
        }

        .starci-core-chat-workspace-layout[data-grammar-chat-workspace-rail-width="standard"] {
            grid-template-columns: minmax(0, 1fr) minmax(16rem, var(--starci-core-rail-standard, 20rem));
        }

        .starci-core-chat-workspace-layout[data-grammar-chat-workspace-rail-width="wide"] {
            grid-template-columns: minmax(0, 1fr) minmax(20rem, var(--starci-core-rail-wide, 24rem));
        }

        .starci-core-chat-workspace-inline-rail {
            display: block;
            min-height: 0;
            min-width: 0;
        }
    }

    @media (prefers-reduced-motion: reduce) {
        [data-grammar-motion="animated"] {
            scroll-behavior: auto;
        }
    }

    /*
     * ============================================================================================
     * SHIPPED OBJECT GEOMETRY (0.4.4)
     * ============================================================================================
     *
     * Everything below used to be a Tailwind utility string inside a Grammar component or its
     * `classNames.ts`. A class only exists if the CONSUMER's Tailwind build scanned the file that
     * spells it, and almost nobody scans `node_modules/@starci/grammar` - so those objects arrived
     * in a consuming app with no box at all. The utilities are gone; the box lives here, selected
     * by the data attributes each component already emits.
     *
     * `!important` appears ONLY where the class lands on a HeroUI part - `Card`, `Accordion`,
     * `Button`, `TextField`, `Input`, `Skeleton`, `ProgressBar`, `ScrollShadow` - whose own rules
     * live in the vendor's `components` layer. That layer is declared AFTER `starci-grammar-common`
     * and therefore wins every normal declaration regardless of specificity; an important
     * declaration in the earlier layer is the only thing that reproduces what the utilities did.
     * Corners come from the theme radius ramp (`--radius-*`), never from a HeroUI v2 radius name
     * such as `rounded-large`, which emits nothing anywhere.
     */

    /* --- Surface card: the card, its label row and its content shell are HeroUI `Card` parts. --- */
    /*
     * THE CARD'S OUTER BOX IS ITS BOUNDARY, exactly as the list's and the accordion's are.
     *
     * `SurfaceCard` is the only one of the three whose root is a HeroUI `Card`, and the vendor's
     * `.card` carries a 1rem padding of its own. That inset moved the card's visible surface AND
     * its label a further 16px inward, so a padded `SurfaceCard` and an unpadded
     * `SurfaceAccordionCard` standing in one column disagreed by 16px at both edges - two members
     * of one family drawing the same boundary in two places. The label row and the content shell
     * were already given `padding: 0 !important` here for the same reason; the root was missed.
     *
     * The card keeps its inset where the contract puts it: `PADDING-4` is claimed by the CONTENT
     * REGION inside the surface, which is where the reader's copy is held off the boundary.
     */
    .starci-core-surface-card {
        display: flex !important;
        width: 100% !important;
        min-width: 0;
        flex-direction: column !important;
        gap: var(--starci-core-section-gap, 0.75rem) !important;
        padding: 0 !important;
    }

    .starci-core-surface-label {
        padding: 0 !important;
    }

    .starci-core-surface {
        padding: 0 !important;
    }

    .starci-core-surface-highlight {
        position: relative;
        height: 100%;
    }

    /* --- Surface list --- */
    .starci-core-surface-fact {
        color: var(--muted, var(--starci-core-muted, GrayText));
        font-size: 0.875rem;
        line-height: 1.25rem;
    }

    .starci-core-surface-fact[data-grammar-surface-depth="nested"] {
        font-size: 0.75rem;
        line-height: 1rem;
    }

    /* --- Empty notice --- */
    .starci-core-empty-notice {
        display: flex;
        min-width: 0;
        flex-direction: column;
        align-items: center;
        gap: 0.75rem;
        padding: 1rem;
        text-align: center;
    }

    /* --- Divider --- */
    .starci-core-divider {
        display: flex;
        min-width: 0;
        flex-direction: row;
        align-items: center;
        gap: 0.75rem;
    }

    .starci-core-divider-rule {
        height: 1px;
        flex: 1 1 0%;
        background: var(--border, var(--separator, var(--starci-core-separator, GrayText)));
    }

    /* --- Icon: an app-owned SVG has no intrinsic box, so usage sizing must ship. --- */
    .starci-core-icon {
        flex: none;
    }

    .starci-core-icon[data-usage="heading"] {
        width: 1.5rem;
        height: 1.5rem;
    }

    .starci-core-icon[data-usage="leading"] {
        width: 1.25rem;
        height: 1.25rem;
    }

    .starci-core-icon[data-usage="chip"] {
        width: 1rem;
        height: 1rem;
    }

    .starci-core-icon-skeleton {
        display: inline-block;
        width: 1.25rem !important;
        height: 1.25rem !important;
        flex: none;
        border-radius: var(--starci-core-pill-radius, 999px) !important;
    }

    /* --- Icon button: a HeroUI `Button` worn as a circle. --- */
    .starci-core-icon-button {
        border-radius: var(--starci-core-pill-radius, 999px) !important;
    }

    /* --- Icon tile --- */
    .starci-core-icon-tile {
        display: inline-flex;
        flex: none;
        align-items: center;
        justify-content: center;
        overflow: hidden;
    }

    .starci-core-icon-tile[data-size="sm"] {
        width: 2rem;
        height: 2rem;
        border-radius: var(--radius-lg, var(--radius, 0.5rem));
    }

    .starci-core-icon-tile[data-size="md"] {
        width: 2.5rem;
        height: 2.5rem;
        border-radius: var(--radius-xl, calc(var(--radius, 0.5rem) * 1.5));
    }

    /* A tone pair is painted only when the plate draws its own glyph. */
    .starci-core-icon-tile[data-tone="neutral"][data-artwork="false"][data-loading="false"] {
        background: var(--default, var(--starci-core-surface-secondary, Canvas));
        color: var(--muted, var(--starci-core-muted, GrayText));
    }

    .starci-core-icon-tile[data-tone="accent"][data-artwork="false"][data-loading="false"] {
        background: var(--accent-soft, var(--starci-core-accent, Highlight));
        color: var(--accent-soft-foreground, var(--starci-core-accent, HighlightText));
    }

    .starci-core-icon-tile[data-tone="success"][data-artwork="false"][data-loading="false"] {
        background: var(--success-soft, var(--success, Canvas));
        color: var(--success-soft-foreground, var(--success-foreground, CanvasText));
    }

    .starci-core-icon-tile[data-tone="warning"][data-artwork="false"][data-loading="false"] {
        background: var(--warning-soft, var(--warning, Canvas));
        color: var(--warning-soft-foreground, var(--warning-foreground, CanvasText));
    }

    .starci-core-icon-tile[data-tone="danger"][data-artwork="false"][data-loading="false"] {
        background: var(--danger-soft, var(--danger, Canvas));
        color: var(--danger-soft-foreground, var(--danger-foreground, CanvasText));
    }

    /* --- Progress: a HeroUI `ProgressBar`, and a resting bar of the same measure. --- */
    .starci-core-progress {
        width: 100% !important;
    }

    .starci-core-progress[data-loading="true"] {
        display: block;
        height: 0.5rem !important;
    }

    /*
     * --- Input ---
     *
     * The reveal toggle sits on top of the control, so the field RESERVES room for it rather than
     * letting the value slide underneath. That inset used to be spelled `pr-9`, a utility no app in
     * this repository writes, so it was generated nowhere and the toggle overlapped the text at
     * every width.
     */
    .starci-core-input {
        display: grid !important;
        min-width: 0;
        gap: 0.5rem !important;
    }

    .starci-core-input-control {
        position: relative;
        display: flex;
        min-width: 0;
        align-items: center;
    }

    .starci-core-input-control[data-reveal="true"] .starci-core-input-field {
        padding-inline-end: 2.75rem !important;
    }

    .starci-core-input-reveal {
        position: absolute;
        inset-inline-end: 0.5rem;
        top: 50%;
        display: inline-flex;
        align-items: center;
        justify-content: center;
        transform: translateY(-50%);
        border: 0;
        background: transparent;
        color: var(--muted, var(--starci-core-muted, GrayText));
        cursor: pointer;
    }

    .starci-core-input-reveal:disabled {
        cursor: default;
    }

    .starci-core-input-reveal :where(svg),
    .starci-core-input-reveal-icon {
        width: 1rem;
        height: 1rem;
    }

    .starci-core-input-reveal-label {
        font-size: 0.75rem;
    }

    .starci-core-input-resting-label {
        width: 33.333333% !important;
        height: 1rem !important;
        border-radius: var(--radius-md, calc(var(--radius, 0.5rem) * 0.75)) !important;
    }

    .starci-core-input-resting-control {
        width: 100% !important;
        height: 2.5rem !important;
        border-radius: var(--field-radius, calc(var(--radius, 0.5rem) * 1.5)) !important;
    }

    /* --- Heading: the FONT rank each level stamps, drawn from the family's own sheet. --- */
    /*
     * `Heading` renders through the vendor's `Typography.Heading`, which sizes `.typography--h1`
     * through `--h4` from the vendor's own sheet. Until 0.4.12 the family answered that with the
     * Tailwind utility classes on the component alone - and a utility class exists only where the
     * CONSUMER's Tailwind build scanned this package's dist, which is the same debt
     * `shipped-geometry.spec.ts` already refuses for layout. A consumer whose scan stopped finding
     * the package measured 36px under a `FONT-4` stamp and 30px under `FONT-3`: the vendor's sizes,
     * under the family's promise. The scale is the family's, so the family's sheet draws it, the way
     * `.starci-core-text` above already draws its own.
     *
     * `!important` because the vendor rule has to lose in either import order - consumers import
     * this sheet both before and after `@heroui/styles`, so layer rank alone cannot decide it. The
     * values re-state what the utilities carry, so nothing moves where a scan still finds them.
     *
     * `display` is the one row a family may re-cut: `offset-pop` gives it its own weight, tracking
     * and 0.96 line height. So only FONT-6's SIZE is important here; its rhythm stays a normal
     * declaration that a later family layer can still own.
     */
    .grammar-common-root [data-component="Heading"][data-scale="standard"][data-level="1"] {
        font-size: 1.25rem !important;
        font-weight: 600 !important;
        letter-spacing: -0.025em !important;
        line-height: 1.75rem !important;
    }

    .grammar-common-root [data-component="Heading"][data-scale="standard"][data-level="2"] {
        font-size: 1rem !important;
        font-weight: 600 !important;
        line-height: 1.5rem !important;
    }

    .grammar-common-root [data-component="Heading"][data-scale="standard"][data-level="3"] {
        font-size: 0.875rem !important;
        font-weight: 500 !important;
        line-height: 1.25rem !important;
    }

    .grammar-common-root [data-component="Heading"][data-scale="standard"][data-level="4"] {
        font-size: 0.75rem !important;
        font-weight: 500 !important;
        line-height: 1rem !important;
    }

    .grammar-common-root [data-component="Heading"][data-scale="display"] {
        font-size: 2.25rem !important;
        font-weight: 600;
        letter-spacing: -0.025em;
        line-height: 1.25;
    }

    /* --- Text: one resolved line of copy, drawn from the attributes it already emits. --- */
    .starci-core-text {
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
        font-size: 1rem;
        font-weight: 400;
        line-height: 1.5rem;
    }

    .starci-core-text[data-size="xs"] {
        font-size: 0.75rem;
        line-height: 1rem;
    }

    .starci-core-text[data-size="sm"] {
        font-size: 0.875rem;
        line-height: 1.25rem;
    }

    .starci-core-text[data-size="metric-lead"] {
        font-size: 1.875rem;
        line-height: 2.25rem;
    }

    .starci-core-text[data-tone="muted"] {
        color: var(--muted, var(--starci-core-muted, GrayText));
    }

    .starci-core-text[data-tone="accent"] {
        color: var(--accent-soft-foreground, var(--starci-core-accent, HighlightText));
    }

    .starci-core-text[data-weight="medium"] { font-weight: 500; }
    .starci-core-text[data-weight="semibold"] { font-weight: 600; }

    .starci-core-text[data-start-content="true"] {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
    }

    .starci-core-text[data-superseded="true"] {
        text-decoration-line: line-through;
    }

    :where(.group)[data-selected="true"] .starci-core-text[data-parent-emphasis="accent-soft"] {
        color: var(--accent-soft-foreground, var(--starci-core-accent, HighlightText));
    }

    /* Authored overflow behaviour: wrap is the resting answer, the other two are opted into. */
    .starci-core-text[data-overflow="wrap"] {
        overflow-wrap: anywhere;
        word-break: break-word;
    }

    .starci-core-text[data-overflow="truncate"] {
        display: block;
        min-width: 0;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
    }

    .starci-core-text[data-overflow="clamp-2"] {
        display: -webkit-box;
        overflow: hidden;
        -webkit-box-orient: vertical;
        -webkit-line-clamp: 2;
        line-clamp: 2;
    }

    /* The resting line keeps its size geometry and hides its copy; no tone is visible to claim. */
    .starci-core-text[data-loading="true"] {
        display: inline-block;
        max-width: 100%;
        border-radius: var(--radius, 0.25rem);
        color: transparent;
        user-select: none;
    }

    .starci-core-text[data-loading="true"][data-size="xs"] { width: 2.5rem; }
    .starci-core-text[data-loading="true"][data-size="sm"] { width: 3rem; }
    .starci-core-text[data-loading="true"][data-size="md"] { width: 10rem; }
    .starci-core-text[data-loading="true"][data-size="metric-lead"] { width: 10rem; }

    /* --- Text action: one recipe, eight appearances, selected by data attributes. --- */
    /*
     * A TextAction is a BUTTON however text-shaped it looks, so the family's pressable floor belongs
     * to the recipe rather than to one appearance. `route` carried it alone until 0.4.10, which left
     * the padding-less appearances - inline, muted, disclosure, plain - collapsing to their line box:
     * a rail action measured 86 x 20 CSS px against a 44px floor. The floor moves up to the recipe
     * here and `route` keeps its own row, now redundant but harmless, so no appearance can lose it
     * again. `min-block-size` rather than `padding-block` for the reason `route` already states:
     * these appearances draw no background at rest, so the extra block size is invisible chrome
     * around unchanged FONT-2/PADDING-2 typography and never a bigger pill. `align-items: center`
     * above keeps the glyph and label centred inside the taller box.
     */
    .starci-core-text-action {
        display: inline-flex;
        width: fit-content;
        min-width: 0;
        min-block-size: var(--starci-core-control-min-size, 2.75rem);
        flex: none;
        align-items: center;
        gap: 0.5rem;
        outline: none;
        text-underline-offset: 4px;
    }

    .starci-core-text-action:disabled {
        opacity: 0.5;
        cursor: default;
    }

    .starci-core-text-action[data-size="xs"] { font-size: 0.75rem; line-height: 1rem; }
    .starci-core-text-action[data-size="sm"] { font-size: 0.875rem; line-height: 1.25rem; }
    .starci-core-text-action[data-size="md"] { font-size: 1rem; line-height: 1.5rem; }

    .starci-core-text-action[data-appearance="inline"] {
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
        font-weight: 500;
    }

    .starci-core-text-action[data-appearance="muted"] {
        color: var(--muted, var(--starci-core-muted, GrayText));
        font-weight: 500;
    }

    .starci-core-text-action[data-appearance="inline"]:hover,
    .starci-core-text-action[data-appearance="inline"]:focus-visible,
    .starci-core-text-action[data-appearance="muted"]:hover,
    .starci-core-text-action[data-appearance="muted"]:focus-visible,
    .starci-core-text-action[data-appearance="disclosure"]:hover,
    .starci-core-text-action[data-appearance="disclosure"]:focus-visible {
        text-decoration-line: underline;
    }

    .starci-core-text-action[data-appearance="choice"] {
        border-radius: var(--starci-core-pill-radius, 999px);
        padding: 0.25rem 0.5rem;
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
        font-weight: 500;
    }

    /*
     * A `route` TextAction is always a destination, so its 44px floor is unconditional rather than
     * scoped to one composition: this is the SAME family law the band's action slots carry, applied
     * to a text-shaped pressable. `min-block-size` is used instead of a taller `padding-block`
     * because `route` draws no background at rest - only `data-current="true"` paints one - so the
     * extra block size is invisible chrome around unchanged FONT-2/PADDING-2 typography, not a
     * bigger pill. The band row still has 3rem (48px) to give a control after its own block inset,
     * so 44px fits with headroom and `--starci-core-band-height` is untouched.
     */
    .starci-core-text-action[data-appearance="route"] {
        border-radius: var(--starci-core-pill-radius, 999px);
        padding: 0.5rem 0.75rem;
        min-block-size: var(--starci-core-control-min-size, 2.75rem);
        color: var(--muted, var(--starci-core-muted, GrayText));
    }

    .starci-core-text-action[data-appearance="section"] {
        border-radius: var(--radius-xl, calc(var(--radius, 0.5rem) * 1.5));
        padding: 0.5rem 0.75rem;
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
    }

    .starci-core-text-action[data-appearance="section"]:hover,
    .starci-core-text-action[data-appearance="section"]:focus-visible {
        background: var(--default, var(--starci-core-surface-secondary, Canvas));
    }

    .starci-core-text-action[data-appearance="tab"] {
        border-block-end: 2px solid transparent;
        padding-block: 0.75rem;
        color: var(--muted, var(--starci-core-muted, GrayText));
    }

    .starci-core-text-action[data-appearance="tab"][data-current="true"] {
        border-block-end-color: var(--accent, var(--starci-core-accent, Highlight));
        color: var(--accent, var(--starci-core-accent, Highlight));
        font-weight: 600;
    }

    .starci-core-text-action[data-appearance="choice"][data-current="true"],
    .starci-core-text-action[data-appearance="route"][data-current="true"],
    .starci-core-text-action[data-appearance="section"][data-current="true"] {
        background: var(--accent-soft, var(--starci-core-accent, Highlight));
        color: var(--accent-soft-foreground, var(--starci-core-accent, HighlightText));
    }

    .starci-core-text-action[data-appearance="route"][data-current="true"],
    .starci-core-text-action[data-appearance="section"][data-current="true"] {
        font-weight: 600;
    }

    .starci-core-text-action[data-appearance="disclosure"] {
        color: var(--accent-soft-foreground, var(--starci-core-accent, HighlightText));
        font-weight: 600;
    }

    .starci-core-text-action[data-appearance="plain"] {
        color: var(--foreground, var(--starci-core-foreground, CanvasText));
        text-decoration-line: none;
    }

    .starci-core-text-action-resting {
        display: inline-flex;
        width: 4rem;
        flex: none;
        color: transparent;
        user-select: none;
    }

    /*
     * --- Button: full width ---
     *
     * A full-width action stretches to its parent and lets its label wrap onto a second line rather
     * than overflow, so the vendor's fixed control height is released to the content.
     */
    .starci-core-button[data-width="fill"] {
        width: 100% !important;
        max-width: 100% !important;
        height: auto !important;
        min-height: var(--starci-core-control-min-size, 2.75rem);
        white-space: normal !important;
    }

    /* --- Chat workspace: the compact rail trigger's resting paint. --- */
    .starci-core-chat-workspace-rail-trigger {
        box-shadow: 0 1px 2px 0 color-mix(in srgb, CanvasText 8%, transparent);
        outline: none;
        transition: background-color var(--starci-core-motion-duration, 180ms) var(--starci-core-motion-easing, cubic-bezier(0.2, 0, 0, 1));
    }

    .starci-core-chat-workspace-rail-trigger:hover {
        background: var(--default, var(--starci-core-surface-secondary, Canvas));
    }

    @media (prefers-reduced-motion: reduce) {
        .starci-core-chat-workspace-rail-trigger {
            transition: none;
        }
    }

}

dist/core/styles.css.content:
@import "../common/styles.css";

@layer starci-grammar-core {
    /*
     * StarCi visual DNA is opt-in through GrammarRoot. It supplies a complete,
     * portable semantic theme while keeping product/UI laws out of CSS.
     */
    .grammar-common-root[data-grammar-family="core"] {
        color-scheme: light;

        --starci-core-accent: #7547ff;
        --starci-core-accent-foreground: oklch(100% 0 0);
        --starci-core-focus: #7248ff;
        --starci-core-canvas: oklch(97.02% 0.0015 354.13);
        --starci-core-surface: oklch(100% 0.0008 354.13);
        --starci-core-surface-secondary: oklch(95.24% 0.0012 354.13);
        --starci-core-foreground: oklch(21.03% 0.0015 354.13);
        --starci-core-muted: oklch(55.17% 0.003 354.13);
        --starci-core-border: oklch(90% 0.0015 354.13);
        --starci-core-separator: oklch(92% 0.0015 354.13);
        --starci-core-success: oklch(73.29% 0.1941 162.85);
        --starci-core-success-foreground: oklch(21.03% 0.0059 162.85);
        --starci-core-warning: oklch(78.19% 0.159 84.37);
        --starci-core-warning-foreground: oklch(21.03% 0.0059 84.37);
        --starci-core-danger: oklch(65.32% 0.2335 37.78);
        --starci-core-danger-foreground: oklch(99.11% 0 0);
        --starci-core-info: oklch(72% 0.17 250);
        --starci-core-info-foreground: oklch(21.03% 0.0059 250);
        --starci-core-page-measure: 80rem;
        --starci-core-reading-measure: 72ch;
        --starci-core-page-inset: var(--grammar-page-inset);
        --starci-core-region-gap: var(--grammar-region-gap);
        --starci-core-section-gap: var(--grammar-section-gap);
        --starci-core-inline-gap: var(--grammar-inline-gap);
        --starci-core-row-gap: var(--grammar-row-gap);
        --starci-core-surface-radius: 1rem;
        --starci-core-control-radius: 0.75rem;
        --starci-core-pill-radius: 999px;
        --starci-core-surface-shadow: 0 8px 28px oklch(21.03% 0.0059 354.13 / 0.07);
        --starci-core-motion-duration: 180ms;
        --starci-core-motion-easing: cubic-bezier(0.2, 0, 0, 1);

        /* HeroUI and existing Grammar anatomy resolve through the same DNA. */
        --accent: var(--starci-core-accent);
        --accent-foreground: var(--starci-core-accent-foreground);
        --focus: var(--starci-core-focus);
        --background: var(--starci-core-canvas);
        --foreground: var(--starci-core-foreground);
        --surface: var(--starci-core-surface);
        --surface-foreground: var(--starci-core-foreground);
        --surface-secondary: var(--starci-core-surface-secondary);
        --surface-secondary-foreground: var(--starci-core-foreground);
        --muted: var(--starci-core-muted);
        --border: var(--starci-core-border);
        --separator: var(--starci-core-separator);
        --success: var(--starci-core-success);
        --success-foreground: var(--starci-core-success-foreground);
        --warning: var(--starci-core-warning);
        --warning-foreground: var(--starci-core-warning-foreground);
        --danger: var(--starci-core-danger);
        --danger-foreground: var(--starci-core-danger-foreground);
        --info: var(--starci-core-info);
        --info-foreground: var(--starci-core-info-foreground);
        --field-background: var(--starci-core-surface);
        --field-border: transparent;
        --field-foreground: var(--starci-core-foreground);
        --field-placeholder: var(--starci-core-muted);
        --radius: var(--starci-core-control-radius);
        --field-radius: var(--starci-core-control-radius);
        --shadow-surface: var(--starci-core-surface-shadow);

        min-width: 0;
        background: var(--starci-core-canvas);
        color: var(--starci-core-foreground);
        font-family: var(--starci-font-sans, ui-sans-serif, system-ui, sans-serif);
    }

    .grammar-common-root[data-grammar-family="core"][data-grammar-theme="dark"] {
        color-scheme: dark;
        --starci-core-canvas: oklch(12% 0.0015 354.13);
        --starci-core-surface: oklch(21.03% 0.003 354.13);
        --starci-core-surface-secondary: oklch(25.7% 0.0023 354.13);
        --starci-core-foreground: oklch(99.11% 0.0015 354.13);
        --starci-core-muted: oklch(70.5% 0.003 354.13);
        --starci-core-border: oklch(28% 0.0015 354.13);
        --starci-core-separator: oklch(25% 0.0015 354.13);
        --starci-core-success: oklch(73.29% 0.1941 162.85);
        --starci-core-success-foreground: oklch(21.03% 0.0059 162.85);
        --starci-core-warning: oklch(82.03% 0.1392 88.38);
        --starci-core-warning-foreground: oklch(21.03% 0.0059 88.38);
        --starci-core-danger: oklch(59.4% 0.1973 36.67);
        --starci-core-danger-foreground: oklch(99.11% 0 0);
        --starci-core-info: oklch(72% 0.17 250);
        --starci-core-info-foreground: oklch(21.03% 0.0059 250);
    }

    /* StarCi labelled surfaces paint one material box around label and content. */
    .grammar-common-root[data-grammar-family="core"]
        .starci-core-surface-card[data-grammar-surface-labelled="true"][data-grammar-frame="bounded"] {
        overflow: hidden;
        border-radius: var(--starci-core-surface-radius, 1rem);
        background: var(--starci-core-surface, var(--surface, Canvas));
        box-shadow: var(--starci-core-surface-shadow, var(--shadow-surface, none));
    }

    .grammar-common-root[data-grammar-family="core"]
        .starci-core-surface-card[data-grammar-surface-labelled="true"][data-grammar-frame="bounded"]
        > [data-grammar-surface-label] {
        padding: var(--starci-core-surface-inset, 1rem) var(--starci-core-surface-inset, 1rem) 0;
    }

    .grammar-common-root[data-grammar-family="core"]
        .starci-core-surface-card[data-grammar-surface-labelled="true"][data-grammar-frame="bounded"]
        > [data-grammar-frame="bounded"],
    .grammar-common-root[data-grammar-family="core"]
        .starci-core-surface-card[data-grammar-surface-labelled="true"][data-grammar-frame="bounded"]
        > [data-grammar-highlight="true"]
        > [data-grammar-frame="bounded"] {
        border: 0;
        border-radius: 0;
        background: transparent;
        box-shadow: none;
    }

@media (prefers-color-scheme: dark) {
        .grammar-common-root[data-grammar-family="core"][data-grammar-theme="system"] {
            color-scheme: dark;
            --starci-core-canvas: oklch(12% 0.0015 354.13);
            --starci-core-surface: oklch(21.03% 0.003 354.13);
            --starci-core-surface-secondary: oklch(25.7% 0.0023 354.13);
            --starci-core-foreground: oklch(99.11% 0.0015 354.13);
            --starci-core-muted: oklch(70.5% 0.003 354.13);
            --starci-core-border: oklch(28% 0.0015 354.13);
            --starci-core-separator: oklch(25% 0.0015 354.13);
            --starci-core-success: oklch(73.29% 0.1941 162.85);
            --starci-core-success-foreground: oklch(21.03% 0.0059 162.85);
            --starci-core-warning: oklch(82.03% 0.1392 88.38);
            --starci-core-warning-foreground: oklch(21.03% 0.0059 88.38);
            --starci-core-danger: oklch(59.4% 0.1973 36.67);
            --starci-core-danger-foreground: oklch(99.11% 0 0);
            --starci-core-info: oklch(72% 0.17 250);
            --starci-core-info-foreground: oklch(21.03% 0.0059 250);
        }
    }

    @media (forced-colors: active) {
        .grammar-common-root[data-grammar-family="core"] {
            --starci-core-accent: Highlight;
            --starci-core-focus: Highlight;
            --starci-core-canvas: Canvas;
            --starci-core-surface: Canvas;
            --starci-core-surface-secondary: Canvas;
            --starci-core-foreground: CanvasText;
            --starci-core-muted: GrayText;
            --starci-core-border: CanvasText;
            --starci-core-separator: CanvasText;
            --starci-core-success: CanvasText;
            --starci-core-success-foreground: Canvas;
            --starci-core-warning: CanvasText;
            --starci-core-warning-foreground: Canvas;
            --starci-core-danger: CanvasText;
            --starci-core-danger-foreground: Canvas;
            --starci-core-info: CanvasText;
            --starci-core-info-foreground: Canvas;
            --starci-core-surface-shadow: none;
        }
    }
}
